import { createI18n, type CreateI18nOptions, type PalamedesI18n } from "@palamedes/core";
// Generated by the build plugin; never resolved in an application browser graph.
import { loadServerCatalog } from "virtual:palamedes/server-catalogs";

/** Options for one request-local i18n instance backed by bundled catalogs. */
export type BundledServerI18nOptions = CreateI18nOptions & {
  /** The active locale selected by the host's request policy. */
  readonly locale: string;
};

/**
 * Load shared immutable content for one locale and create isolated request state.
 *
 * `virtual:palamedes/server-catalogs` is supplied by the build plugin
 * (`@palamedes/vite-plugin`). Importing this subpath outside such a build
 * fails to resolve; there is no source-text fallback.
 */
export async function createBundledServerI18n(
  options: BundledServerI18nOptions,
): Promise<PalamedesI18n> {
  const messages = await loadServerCatalog(options.locale);
  const i18n = createI18n(options);
  i18n.load(options.locale, messages);
  return i18n;
}
